import os
import sys
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def resolve_note(name: str) -> Path | None:
    """Resolve `name` to a path strictly inside NOTES_DIR (relative to the
    working directory), or None if it would land outside it (absolute paths,
    `..` escapes, symlinks pointing out, sibling dirs sharing the prefix) or
    is not a valid path (e.g. contains a NUL byte). Does not require the
    file to exist."""
    if "\x00" in name:
        return None
    try:
        if os.path.isabs(name) or Path(name).is_absolute():
            return None
        base = Path(NOTES_DIR).resolve()
        candidate = (base / name).resolve()
    except (ValueError, OSError, RuntimeError):
        return None
    if candidate == base or not candidate.is_relative_to(base):
        return None
    return candidate


def read_note(name: str) -> str:
    """Return the text of the file `name` inside NOTES_DIR, or "" if it is
    missing, unreadable, not a regular file, or outside NOTES_DIR."""
    path = resolve_note(name)
    if path is None:
        return ""
    try:
        if not path.is_file():
            return ""
        return path.read_text(encoding="utf-8", errors="replace")
    except (OSError, ValueError):
        return ""


def count_readable(names: list[str]) -> int:
    """Count the entries of `names` that are regular files inside NOTES_DIR
    that can be opened and read. Each entry is counted separately (duplicates
    count twice). Names are untrusted: none may reach a file outside NOTES_DIR,
    and no name may raise an exception."""
    count = 0
    for name in names:
        path = resolve_note(name)
        if path is None:
            continue
        try:
            if not path.is_file():
                continue
            with path.open("rb") as f:
                f.read(1)
        except (OSError, ValueError):
            continue
        count += 1
    return count


@pytest.fixture
def workspace(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "b.txt").write_text("beta")
    (notes / "empty.txt").write_text("")
    (notes / "sub" / "c.txt").write_text("gamma")
    (tmp_path / "secret.txt").write_text("top secret")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("evil")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_read_note_returns_content(workspace: Path) -> None:
    assert read_note("a.txt") == "alpha"
    assert read_note("sub/c.txt") == "gamma"


def test_read_note_missing_is_empty(workspace: Path) -> None:
    assert read_note("nope.txt") == ""


def test_read_note_blocks_traversal(workspace: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""


def test_count_empty_list(workspace: Path) -> None:
    assert count_readable([]) == 0


def test_count_basic(workspace: Path) -> None:
    assert count_readable(["a.txt", "b.txt", "missing.txt"]) == 2


def test_count_includes_empty_file(workspace: Path) -> None:
    assert count_readable(["empty.txt"]) == 1


def test_count_duplicates_counted_each(workspace: Path) -> None:
    assert count_readable(["a.txt", "a.txt", "b.txt"]) == 3


def test_count_nested_file(workspace: Path) -> None:
    assert count_readable(["sub/c.txt"]) == 1


def test_count_inner_dotdot_staying_inside(workspace: Path) -> None:
    assert count_readable(["sub/../a.txt"]) == 1


def test_count_directory_is_not_a_file(workspace: Path) -> None:
    assert count_readable(["sub", "", ".", "./"]) == 0


def test_count_rejects_parent_traversal(workspace: Path) -> None:
    assert count_readable(["../secret.txt", "sub/../../secret.txt"]) == 0


def test_count_rejects_sibling_with_shared_prefix(workspace: Path) -> None:
    assert count_readable(["../notes_evil/x.txt"]) == 0


def test_count_rejects_absolute_paths(workspace: Path) -> None:
    secret = str(workspace / "secret.txt")
    inside = str(workspace / NOTES_DIR / "a.txt")
    assert count_readable([secret]) == 0
    assert count_readable([inside]) == 0


def test_count_rejects_prefixed_notes_name(workspace: Path) -> None:
    # "notes/a.txt" means notes/notes/a.txt, which does not exist.
    assert count_readable([f"{NOTES_DIR}/a.txt"]) == 0


def test_count_rejects_symlink_escaping_notes(workspace: Path) -> None:
    link = workspace / NOTES_DIR / "link.txt"
    os.symlink(workspace / "secret.txt", link)
    assert count_readable(["link.txt"]) == 0
    assert read_note("link.txt") == ""


def test_count_rejects_symlinked_dir_escaping_notes(workspace: Path) -> None:
    os.symlink(workspace / "notes_evil", workspace / NOTES_DIR / "evil")
    assert count_readable(["evil/x.txt"]) == 0


def test_count_nul_byte_does_not_raise(workspace: Path) -> None:
    assert count_readable(["a.txt\x00", "a\x00.txt"]) == 0


def test_count_very_long_name_does_not_raise(workspace: Path) -> None:
    assert count_readable(["x" * 10_000]) == 0


@pytest.mark.skipif(
    sys.platform == "win32" or (hasattr(os, "geteuid") and os.geteuid() == 0),
    reason="permission bits not enforced",
)
def test_count_unreadable_file_not_counted(workspace: Path) -> None:
    locked = workspace / NOTES_DIR / "locked.txt"
    locked.write_text("hidden")
    locked.chmod(0)
    try:
        assert count_readable(["locked.txt", "a.txt"]) == 1
        assert read_note("locked.txt") == ""
    finally:
        locked.chmod(0o600)


def test_resolve_note_inside_and_outside(workspace: Path) -> None:
    inside = resolve_note("a.txt")
    assert inside is not None
    assert inside.resolve() == (workspace / NOTES_DIR / "a.txt").resolve()
    assert resolve_note("../secret.txt") is None
    assert resolve_note(str(workspace / "secret.txt")) is None
    assert resolve_note("a\x00.txt") is None
